// Writes ../preview-data.js: the five smoothed series the card preview draws, computed by model.js.
// Run after any change to model.js: node projects/stereo/tools/make-preview-data.js
// tests/model.test.js fails if the file no longer equals a fresh computation.
'use strict';
var fs = require('fs');
var path = require('path');
var S = require(path.join(__dirname, '..', 'model.js'));

var data = S.previewSeries();
var text = '/* Stereo: the card preview\'s five series (firmware fault, a week\'s moving average, beside the truth).\n' +
  ' * Generated by tools/make-preview-data.js from model.js; tests/model.test.js checks it equals a fresh run.\n' +
  ' * Loaded only in preview mode, so the card need not simulate the city on load. */\n' +
  'window.StereoPreviewData = ' + JSON.stringify(data) + ';\n';
var out = path.join(__dirname, '..', 'preview-data.js');
fs.writeFileSync(out, text);
console.log('wrote ' + out + ' (' + text.length + ' bytes)');
